-- Garden Care: live export 2026-10-02 plus source-11 from the 1 Oct snapshot.
-- Source: https://almaiso-garden-care.psytek332073.chatgpt.site/api/inspections
-- 21 tasks: 6 open, 15 resolved. source-11 is open, unassigned, and was not on the live site.
-- version is the live content hash (text). source-11 keeps snapshot version '1'.
CREATE TABLE IF NOT EXISTS inspections (
 id text PRIMARY KEY, date text NOT NULL, issue text NOT NULL,
 cause text NOT NULL, solution text NOT NULL, assignee text NOT NULL,
 resolved boolean NOT NULL DEFAULT false, notes text NOT NULL,
 photo text NOT NULL, completed_date text, version text NOT NULL
);
